METER_LIST = ("TINY", "CLASSIC")
SCAN_LIST_CHOICES = tuple(
    ["リスト %d" % index for index in range(1, 25)] + ["全チャンネル"])


def _make_backlight_list():
    values = ["OFF"]
    for seconds in range(5, 301, 5):
        if seconds < 60:
            values.append("%d秒" % seconds)
        elif seconds % 60 == 0:
            values.append("%d分" % (seconds // 60))
        else:
            values.append("%d分%02d秒" % (seconds // 60, seconds % 60))
    values.append("常時点灯")
    return tuple(values)


def _make_auto_keypad_lock_list():
    values = ["OFF"]
    for seconds in range(15, 601, 15):
        values.append("%d分%02d秒" % (seconds // 60, seconds % 60))
    return tuple(values)


def _make_sleep_timer_list():
    return tuple(["OFF"] + ["%d分" % minutes for minutes in range(1, 121)])


def _make_scan_resume_list():
    values = ["停止"]
    values.extend("キャリア解消後 %.2f秒" % (value * 0.25)
                  for value in range(1, 81))
    values.extend("タイムアウト後 %d秒" % ((value - 80) * 5)
                  for value in range(81, 105))
    return tuple(values)


BACKLIGHT_LIST = _make_backlight_list()
AUTO_KEYPAD_LOCK_LIST = _make_auto_keypad_lock_list()
SLEEP_TIMER_LIST = _make_sleep_timer_list()
SCAN_RESUME_LIST = _make_scan_resume_list()

# ACTION_OPT_t in the RX-only build ends at ACTION_OPT_RXA (20).  Keep the
# numeric order identical to settings.h so existing assignments survive a
# download/upload round trip.  Entries blocked or compiled as no-ops are
# labelled explicitly instead of exposing transmit controls as usable ones.
ACTION_LIST = (
    "なし", "ライト", "電源（RX-only無効）", "モニター", "スキャン",
    "VOX（無効）", "アラーム（無効）", "FMラジオ", "1750Hz（RX-only無効）",
    "キーロック", "A/B切替", "VFO/メモリ切替", "モード切替", "最低輝度解除",
    "受信モード", "受信専用", "PTT（RX-only無効）", "W/N",
    "バックライト", "ミュート", "受信音声",
)


